// Clinic Appointment Manager
// Class 12 Computer Science with C++ - Project
// Uses: classes, vectors, file handling, exceptions, sorting, searching
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <string>
#include <algorithm>
#include <stdexcept>
#include <cctype>
#include <cstdlib>
using namespace std;

// ---------- user-defined exception (Chapter 1) ----------
class SlotTaken : public runtime_error {
public:
    SlotTaken(const string& doc, const string& date, const string& time)
        : runtime_error(doc + " already has an appointment on " + date + " at " + time) {}
};

// ---------- one record (Chapter 8: one tuple) ----------
struct Appointment {
    int id;
    string patient, phone, doctor, date, time;   // date: YYYY-MM-DD, time: HH:MM
};

// ---------- safe input helpers ----------
string readLine(const string& prompt) {
    cout << prompt;
    string s;
    if (!getline(cin, s)) exit(0);                       // input ended
    if (s.empty()) throw invalid_argument("Value cannot be empty");
    if (s.find(',') != string::npos) throw invalid_argument("Commas are not allowed");
    return s;
}

int readInt(const string& prompt) {
    string s = readLine(prompt);
    size_t used = 0;
    int v = 0;
    try { v = stoi(s, &used); }                          // stoi throws for "abc"
    catch (const exception&) { used = 0; }
    if (used == 0 || used != s.size()) throw invalid_argument("Please type a whole number");
    return v;
}

// ---------- the main class ----------
class Clinic {
    vector<Appointment> appts;
    int nextId = 1;
    const string fileName = "appointments.csv";

    static bool validPhone(const string& p) {
        return p.size() == 10 &&
               all_of(p.begin(), p.end(), [](unsigned char c) { return
isdigit(c); });
    }
    static bool validDate(const string& d) { return d.size() == 10 && d[4] ==
'-' && d[7] == '-'; }
    static bool validTime(const string& t) { return t.size() == 5 && t[2] ==
':'; }

    static void print(const Appointment& a) {
        cout << a.id << "\t" << a.date << " " << a.time << "\t"
             << a.doctor << "\t" << a.patient << " (" << a.phone << ")" <<
endl;
    }

public:
    Clinic()  { load(); }
    ~Clinic() { save(); }                                // RAII: saved on exit

    // Chapter 2: read records from a text (CSV) file
    void load() {
        ifstream fin(fileName);
        if (!fin) return;                                // first run: no file yet
        string line;
        while (getline(fin, line)) {
            stringstream ss(line);
            Appointment a;
            string id;
            getline(ss, id, ',');
            getline(ss, a.patient, ',');
            getline(ss, a.phone, ',');
            getline(ss, a.doctor, ',');
            getline(ss, a.date, ',');
            getline(ss, a.time, ',');
            if (id.empty()) continue;
            a.id = stoi(id);
            appts.push_back(a);
            nextId = max(nextId, a.id + 1);
        }
    }

    void save() const {
        ofstream fout(fileName);
        for (const auto& a : appts)
            fout << a.id << ',' << a.patient << ',' << a.phone << ',' <<
a.doctor << ','
                 << a.date << ',' << a.time << '\n';
    }

    void book() {
        Appointment a;
        a.patient = readLine("Patient name: ");
        a.phone   = readLine("Mobile (10 digits): ");
        if (!validPhone(a.phone)) throw invalid_argument("Mobile number must have exactly 10 digits");
        a.doctor  = readLine("Doctor: ");
        a.date    = readLine("Date (YYYY-MM-DD): ");
        if (!validDate(a.date)) throw invalid_argument("Date must look like 2026-11-05");
        a.time    = readLine("Time (HH:MM): ");
        if (!validTime(a.time)) throw invalid_argument("Time must look like 10:30");

        for (const auto& b : appts)                      // Chapter 6: linear search
            if (b.doctor == a.doctor && b.date == a.date && b.time == a.time)
                throw SlotTaken(a.doctor, a.date, a.time);

        a.id = nextId++;
        appts.push_back(a);
        save();
        cout << "Booked. Appointment ID: " << a.id << endl;
    }

    void cancel(int id) {
        auto it = find_if(appts.begin(), appts.end(),
                          [id](const Appointment& a) { return a.id == id; });
        if (it == appts.end()) throw out_of_range("No appointment with ID " +
to_string(id));
        appts.erase(it);
        save();
        cout << "Appointment " << id << " cancelled" << endl;
    }

    void showAll() const {
        if (appts.empty()) { cout << "No appointments" << endl; return; }
        vector<Appointment> v = appts;
        sort(v.begin(), v.end(), [](const Appointment& x, const Appointment&
y) {   // Chapter 5
            if (x.date != y.date) return x.date < y.date;
            return x.time < y.time;
        });
        cout << "ID\tDate       Time\tDoctor\tPatient" << endl;
        for (const auto& a : v) print(a);
    }

    void doctorDay(const string& doctor, const string& date) const {
        vector<Appointment> v;
        for (const auto& a : appts)
            if (a.doctor == doctor && a.date == date) v.push_back(a);
        if (v.empty()) { cout << "No appointments for " << doctor << " on "
<< date << endl; return; }
        sort(v.begin(), v.end(), [](const Appointment& x, const Appointment&
y) { return x.time < y.time; });
        cout << doctor << " on " << date << ": " << v.size() << " patient(s)"
<< endl;
        for (const auto& a : v) print(a);
    }

    void searchByPhone(const string& phone) const {
        int found = 0;
        for (const auto& a : appts)
            if (a.phone == phone) { print(a); found++; }
        if (found == 0) cout << "No appointments for " << phone << endl;
    }
};

int main() {
    Clinic clinic;
    while (true) {
        cout << "\n=== CLINIC APPOINTMENT MANAGER ===\n"
             << "1.Book  2.Cancel  3.Show all  4.Doctor's day  5.Search by mobile  0.Exit\n";
        try {
            int ch = readInt("Choice: ");
            if (ch == 0) break;
            switch (ch) {
                case 1: clinic.book(); break;
                case 2: clinic.cancel(readInt("Appointment ID: ")); break;
                case 3: clinic.showAll(); break;
                case 4: {
                    string d  = readLine("Doctor: ");
                    string dt = readLine("Date (YYYY-MM-DD): ");
                    clinic.doctorDay(d, dt);
                    break;
                }
                case 5: clinic.searchByPhone(readLine("Mobile: ")); break;
                default: cout << "Please choose 0 to 5" << endl;
            }
        }
        catch (const SlotTaken& e) { cout << "Slot not free: " << e.what() <<
endl; }
        catch (const exception& e) { cout << "Error: " << e.what() << endl; }
    }
    cout << "Data saved. Goodbye!" << endl;
    return 0;
}
